{"implementation":"def solve(case):
    threshold = case.get('threshold')
    calls = case.get('calls')
    if threshold is None or calls is None:
        raise ValueError('Missing threshold or calls')
    accepted_call_ids = []
    diagnostics = []
    for call in calls:
        call_id = call.get('call_id')
        loss_without = call.get('loss_without_call')
        loss_with = call.get('loss_with_call')
        tokens = call.get('prediction_tokens')
        parseable = call.get('parseable')
        if any(x is None for x in [call_id, loss_without, loss_with, tokens, parseable]):
            raise ValueError('Missing field in call')
        if tokens <= 0:
            raise ValueError('prediction_tokens must be positive')
        gain = loss_without - loss_with
        normalized_gain = gain / tokens
        accepted = parseable and normalized_gain >= threshold
        diag = {
            'accepted': accepted,
            'call_id': call_id,
            'normalized_gain': round(normalized_gain, 6)
        }
        diagnostics.append(diag)
        if accepted:
            accepted_call_ids.append(call_id)
    return {
        'accepted_call_ids': accepted_call_ids,
        'diagnostics': diagnostics
    }"}
